CREATE SCHEMA IF NOT EXISTS event;

CREATE TABLE IF NOT EXISTS event.events (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    event_type_id UUID,
    stage_id UUID NOT NULL,
    kanban_state event_kanban_state NOT NULL DEFAULT 'normal',
    date_begin TIMESTAMPTZ NOT NULL,
    date_end TIMESTAMPTZ NOT NULL,
    date_tz TEXT NOT NULL DEFAULT 'UTC',
    is_multi_slots BOOLEAN NOT NULL DEFAULT FALSE,
    event_slot_count INTEGER NOT NULL DEFAULT 1,
    seats_limited BOOLEAN NOT NULL DEFAULT FALSE,
    seats_max INTEGER NOT NULL DEFAULT 0 CHECK (seats_max >= 0),
    address_id UUID,
    organizer_id UUID,
    user_id UUID,
    company_id UUID,
    event_url TEXT,
    badge_format event_badge_format NOT NULL DEFAULT 'a4_french_fold',
    is_published BOOLEAN NOT NULL DEFAULT FALSE,
    date_publish TIMESTAMPTZ,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_events_date_begin_date_end ON event.events (date_begin, date_end);

