CREATE INDEX IF NOT EXISTS idx_events_metadata_created_at ON event.events ((metadata->>'created_at'));
CREATE INDEX IF NOT EXISTS idx_events_metadata_updated_at ON event.events ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION event.events_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS events_insert_audit ON event.events;
CREATE TRIGGER events_insert_audit BEFORE INSERT ON event.events
    FOR EACH ROW EXECUTE FUNCTION event.events_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS events_update_audit ON event.events;
CREATE TRIGGER events_update_audit BEFORE UPDATE ON event.events
    FOR EACH ROW EXECUTE FUNCTION event.events_audit_timestamp();

